pub enum TrendingDecision {
    Pass,
    Reject(TrendingRejectReason),
}

pub fn evaluate(cfg: &TrendingFilterConfig, candidate: &LaunchCandidate) -> TrendingDecision {
    if candidate.liquidity_usd < cfg.min_liquidity_usd {
        return TrendingDecision::Reject(TrendingRejectReason::LiquidityTooLow);
    }
    if candidate.txns_h24 < cfg.min_txns_h24 {
        return TrendingDecision::Reject(TrendingRejectReason::TxnsH24TooLow);
    }
    if cfg.min_volume_24h_usd > 0.0 && candidate.volume_24h_usd < cfg.min_volume_24h_usd {
        return TrendingDecision::Reject(TrendingRejectReason::VolumeTooLow);
    }
    if candidate.m5_change_pct < cfg.min_price_change_5m_pct {
        return TrendingDecision::Reject(TrendingRejectReason::PriceChange5mTooLow);
    }
    if candidate.pair_age_sec < cfg.min_pair_age_sec {
        return TrendingDecision::Reject(TrendingRejectReason::PairAgeTooLow);
    }
    if candidate.market_cap_usd < cfg.min_market_cap_usd {
        return TrendingDecision::Reject(TrendingRejectReason::MarketCapTooLow);
    }
    if cfg.max_market_cap_usd > 0.0 && candidate.market_cap_usd > cfg.max_market_cap_usd {
        return TrendingDecision::Reject(TrendingRejectReason::MarketCapTooHigh);
    }
    if cfg.buy_sell_ratio_required && candidate.buy_sell_ratio_h1 < cfg.min_buy_sell_ratio_h1 {
        return TrendingDecision::Reject(TrendingRejectReason::BuySellRatioTooLow);
    }
    TrendingDecision::Pass
}

